import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import {
  Shield, LayoutDashboard, Users, AlertTriangle,
  Activity, LogOut, User, Lock, FileText
} from 'lucide-react';

const Sidebar = ({ role }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, logout } = useAuth();

  const adminLinks = [
    { path: '/admin/dashboard', icon: LayoutDashboard, label: 'Dashboard' },
    { path: '/admin/users', icon: Users, label: 'Users' },
    { path: '/admin/threats', icon: AlertTriangle, label: 'Threats' },
    { path: '/admin/logs', icon: FileText, label: 'API Logs' },
  ];

  const userLinks = [
    { path: '/user/dashboard', icon: LayoutDashboard, label: 'Dashboard' },
    { path: '/user/activity', icon: Activity, label: 'My Activity' },
    { path: '/user/profile', icon: User, label: 'Profile' },
  ];

  const links = role === 'ADMIN' ? adminLinks : userLinks;

  const handleLogout = async () => {
    await logout();
    navigate('/login');
  };

  return (
    <div style={styles.sidebar}>
      {/* Logo */}
      <div style={styles.logo}>
        <div style={styles.logoIcon}>
          <Shield size={20} color="#00d4ff" />
        </div>
        <div>
          <div style={styles.logoText}>ZeroTrust</div>
          <div style={styles.logoRole}>{role}</div>
        </div>
      </div>

      {/* User info */}
      <div style={styles.userCard}>
        <div style={styles.userAvatar}>
          {role === 'ADMIN' ? <Lock size={16} /> : <User size={16} />}
        </div>
        <div>
          <div style={styles.userName}>{user?.username}</div>
          <div style={styles.userStatus}>
            <span style={styles.dot} />
            Active
          </div>
        </div>
      </div>

      {/* Nav */}
      <nav style={styles.nav}>
        {links.map(({ path, icon: Icon, label }) => {
          const active = location.pathname === path;
          return (
            <button
              key={path}
              onClick={() => navigate(path)}
              style={{ ...styles.navBtn, ...(active ? styles.navBtnActive : {}) }}
            >
              <Icon size={17} />
              <span>{label}</span>
              {active && <div style={styles.activeDot} />}
            </button>
          );
        })}
      </nav>

      {/* Logout */}
      <button onClick={handleLogout} style={styles.logoutBtn}>
        <LogOut size={16} />
        <span>Logout</span>
      </button>
    </div>
  );
};

const styles = {
  sidebar: {
    width: '220px',
    minHeight: '100vh',
    background: '#080f1e',
    borderRight: '1px solid rgba(0, 212, 255, 0.1)',
    display: 'flex',
    flexDirection: 'column',
    padding: '24px 16px',
    fontFamily: "'JetBrains Mono', monospace",
    flexShrink: 0,
  },
  logo: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    marginBottom: '24px',
    paddingBottom: '20px',
    borderBottom: '1px solid rgba(255,255,255,0.06)',
  },
  logoIcon: {
    background: 'rgba(0, 212, 255, 0.1)',
    border: '1px solid rgba(0, 212, 255, 0.2)',
    borderRadius: '8px',
    padding: '8px',
    display: 'flex',
  },
  logoText: { color: '#fff', fontSize: '15px', fontWeight: '700' },
  logoRole: { color: '#00d4ff', fontSize: '9px', letterSpacing: '0.15em', textTransform: 'uppercase' },
  userCard: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    background: 'rgba(255,255,255,0.03)',
    borderRadius: '10px',
    padding: '12px',
    marginBottom: '24px',
  },
  userAvatar: {
    width: '34px',
    height: '34px',
    background: 'rgba(0, 212, 255, 0.15)',
    borderRadius: '8px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    color: '#00d4ff',
  },
  userName: { color: '#fff', fontSize: '13px', fontWeight: '600' },
  userStatus: { display: 'flex', alignItems: 'center', gap: '5px', color: '#22cc77', fontSize: '11px' },
  dot: {
    width: '6px',
    height: '6px',
    background: '#22cc77',
    borderRadius: '50%',
  },
  nav: { flex: 1, display: 'flex', flexDirection: 'column', gap: '4px' },
  navBtn: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    background: 'transparent',
    border: 'none',
    borderRadius: '8px',
    padding: '10px 12px',
    color: '#8899aa',
    fontSize: '13px',
    fontFamily: 'inherit',
    cursor: 'pointer',
    textAlign: 'left',
    width: '100%',
    position: 'relative',
    transition: 'all 0.2s',
  },
  navBtnActive: {
    background: 'rgba(0, 212, 255, 0.08)',
    color: '#00d4ff',
    borderLeft: '2px solid #00d4ff',
  },
  activeDot: {
    position: 'absolute',
    right: '12px',
    width: '6px',
    height: '6px',
    background: '#00d4ff',
    borderRadius: '50%',
  },
  logoutBtn: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    background: 'rgba(255, 80, 80, 0.08)',
    border: '1px solid rgba(255, 80, 80, 0.15)',
    borderRadius: '8px',
    padding: '10px 12px',
    color: '#ff6b6b',
    fontSize: '13px',
    fontFamily: 'inherit',
    cursor: 'pointer',
    marginTop: '8px',
    width: '100%',
  },
};

export default Sidebar;
